SELECT 
-- {% if select %}
artist.*
${REPLACE_ARTIST_SELECT}
--

--
-- {% else %}
-- artist.*
	${REPLACE_ARTIST_SELECT_REDUCED}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`artist` artist
--

--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}

SELECT 
-- {% if select %}
artist.*
--	, artist.`artist_id`
--	, artist.`artist_name`
--

--
-- {% else %}
-- artist.*
	${SELECT_REDUCED}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`artist` artist
--

--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}

-- [list of duplicated columns below]
-- artist_id [artist_song,artist]
-- song_id [artist_song,song]


SELECT 
-- {% if select %}
artist_song.*
${REPLACE_ARTIST_SONG_SELECT}
--
${REPLACE_ARTIST_JOIN(artist)}
${REPLACE_SONG_JOIN(song)}
--
-- {% else %}
-- artist_song.*
	${REPLACE_ARTIST_SONG_SELECT_REDUCED}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`artist_song` artist_song
--
LEFT JOIN `${SCHEMA}`.`artist` artist ON (artist_song.`artist_id` = artist.`artist_id`)
LEFT JOIN `${SCHEMA}`.`song` song ON (artist_song.`song_id` = song.`song_id`)
--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}

