-- {% else %}
-- song_genre.*
	${REPLACE_SONG_GENRE_SELECT_REDUCED}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`song_genre` song_genre
--
-- LEFT JOIN `${SCHEMA}`.`genre` genre ON (song_genre.`genre_id` = genre.`genre_id`)
LEFT JOIN `${SCHEMA}`.`song` song ON (song_genre.`song_id` = song.`song_id`)
--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}
